// db.js — the shared Prisma client (Prisma ORM 7). Prisma 7 talks to PostgreSQL through a driver
// adapter; @prisma/adapter-pg uses the same `pg` driver (and connection pool) as before.
//
// The client is generated by `npm run generate` (also on `npm install`) into src/generated/prisma as
// TypeScript ES modules. Node 22.18+/24 runs those directly and lets this CommonJS code require() them.
require('dotenv').config({ quiet: true });
const { PrismaPg } = require('@prisma/adapter-pg');
const { PrismaClient, Prisma } = require('./generated/prisma/client.ts');

// Neon requires SSL, but a local Postgres (development/testing) does not.
// Set PGSSL=disable, or point DATABASE_URL at localhost, to turn SSL off.
const url = process.env.DATABASE_URL || '';
const isLocal = /@(localhost|127\.0\.0\.1)|host=\/|^postgres(ql)?:\/\/[^@]*\/?\?host=/.test(url);
const useSsl = process.env.PGSSL !== 'disable' && !isLocal;

// pg already treats sslmode=require as verify-full and warns that this will change; say verify-full
// explicitly so the behaviour stays the same. (DATABASE_URL keeps sslmode=require for the Prisma
// CLI, whose migration engine cannot connect with verify-full.)
const driverUrl = url.replace(/([?&]sslmode=)(require|prefer|verify-ca)\b/, '$1verify-full');
const adapter = new PrismaPg({ connectionString: driverUrl, ssl: useSsl ? { rejectUnauthorized: false } : false });
const prisma = new PrismaClient({ adapter });

module.exports = prisma;
module.exports.Prisma = Prisma;
